#!/usr/bin/env python3
"""Post-hoc, information only: does a regex on the coach's own "Role =" line match Jev's role Score?

Run after trajectory.py --score. Nothing here is part of the pre-registered kill test;
it exists so "Jev reads the depth-chart role" is not re-proposed without its baseline.
"""
import re
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent))
import trajectory as t
from scipy import stats

STATED = re.compile(r"role\s*[=:]\s*([^.;\n]*)", re.I)


def rank(text):
    """The coach's stated role as an ordinal, or None when the words do not settle it."""
    if text is None:
        return None
    if re.search(r"\bstart", text):
        return 3
    if re.search(r"rotation|contributor|situational|package", text):
        return 2
    if re.search(r"back ?up|special teams|competing", text):
        return 1
    if re.search(r"develop|scout|redshirt", text):
        return 0
    return None


def main() -> None:
    rows, run1 = t.master(), t.read_run(1)
    athletes = {a["athlete_id"]: a for a in t.load_athletes()}
    number = lambda v: float(v) if v not in (None, "", "NA") else None
    snaps = {i: number(rows[i].get("snaps_blended")) for i in rows}
    matched = [i for i in run1 if snaps.get(i) is not None]

    stated = {}
    for i, a in athletes.items():
        hit = STATED.search(a["notes"]["PC"])
        stated[i] = hit.group(1).strip().lower() if hit else None
    print(f"PC notes stating a role: {sum(v is not None for v in stated.values())} of 99; "
          f"{sum(stated[i] is not None for i in matched)} of the 34 matched")

    ranks = {i: rank(stated.get(i)) for i in matched}
    usable = [i for i in matched if ranks[i] is not None]
    print(f"regex parsed a rank for {len(usable)} of the 34")
    if len(usable) >= 3:
        r = stats.spearmanr([ranks[i] for i in usable], [snaps[i] for i in usable])
        j = stats.spearmanr([run1[i]["role"] for i in usable], [snaps[i] for i in usable])
        a = stats.spearmanr([run1[i]["role"] for i in usable], [ranks[i] for i in usable])
        print(f"REGEX role vs snaps        : rho {r.statistic:.3f} (p {r.pvalue:.3f}, n {len(usable)})")
        print(f"JEV   role vs snaps (same n): rho {j.statistic:.3f} (p {j.pvalue:.3f})")
        print(f"Jev role vs regex role      : rho {a.statistic:.3f}")


